async def test_api_tasks_channel_on_tasks_updated_delivers_contract_valid_payloads(rig):
    client, socket = rig
    await client.register_scenario(
        {
            "topic": "api:tasks:thread:test-id",
            "onJoin": [
                {"type": "autoReply"},
                {"type": "autoPush", "event": "tasks_updated"},
            ],
        }
    )
    channel = await ApiTasksChannel.join_thread(socket, "test-id")
    future: asyncio.Future = asyncio.get_event_loop().create_future()

    def handler(payload):
        if not future.done():
            future.set_result(payload)

    channel.on_tasks_updated(handler)
    payload = await asyncio.wait_for(future, timeout=1.0)
    assert payload is not None


